import{_ as a,o as t,c as n,a2 as e}from"./chunks/framework.XXezeKOl.js";const u=JSON.parse('{"title":"如何选择模型","description":"从能力、延迟、成本、上下文、合规和部署方式等维度，建立一套可落地的模型选型方法。","frontmatter":{"title":"如何选择模型","description":"从能力、延迟、成本、上下文、合规和部署方式等维度，建立一套可落地的模型选型方法。"},"headers":[],"relativePath":"guide/02-llm-basics/choosing-models.md","filePath":"guide/02-llm-basics/choosing-models.md","lastUpdated":null}'),i={name:"guide/02-llm-basics/choosing-models.md"};function l(r,s,d,p,o,h){return t(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="如何选择模型" tabindex="-1">如何选择模型 <a class="header-anchor" href="#如何选择模型" aria-label="Permalink to &quot;如何选择模型&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">学习目标</p><ul><li>掌握模型选型的关键维度：能力、延迟、成本、上下文、合规与部署</li><li>理解闭源 API、开源权重、本地部署各自的取舍</li><li>学会用&quot;小评估集 + 实测&quot;代替看排行榜做决策</li><li>知道如何在架构上为更换模型留出余地</li></ul></div><p>模型更新的速度很快，今天的&quot;最强模型&quot;几个月后可能就被超越。所以本文不推荐具体型号，而是给出一套<strong>不会过时的选型方法</strong>。真正决定选哪个模型的，应该是你自己的任务和数据，而不是排行榜或宣传。</p><h2 id="选型维度" tabindex="-1">选型维度 <a class="header-anchor" href="#选型维度" aria-label="Permalink to &quot;选型维度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>要问的问题</th><th>说明</th></tr></thead><tbody><tr><td>任务能力</td><td>在我的任务上答得对吗？</td><td>通用排行榜只能参考，必须在自己的数据上测</td></tr><tr><td>指令遵循</td><td>能否稳定遵守格式和约束？</td><td>对 Agent 来说往往比&quot;聪明&quot;更重要</td></tr><tr><td>Tool Calling</td><td>工具选择和参数生成是否可靠？</td><td>决定能否做好 Agent，单独评估</td></tr><tr><td>延迟</td><td>首 Token 时间、生成速度是多少？</td><td>交互场景对首 Token 延迟敏感</td></tr><tr><td>成本</td><td>单次任务平均花多少钱？</td><td>按&quot;每完成一个任务的成本&quot;算，而不是看单价</td></tr><tr><td>上下文窗口</td><td>够不够装下我的典型输入？</td><td>窗口大不等于长文本效果好</td></tr><tr><td>多模态</td><td>需要看图、读 PDF、听语音吗？</td><td>见 <a href="/guide/03-llm-api/multimodal">多模态输入</a></td></tr><tr><td>语言</td><td>中文表现如何？</td><td>中文场景务必用中文数据测试</td></tr><tr><td>合规与数据</td><td>数据能否出境？能否被用于训练？</td><td>企业场景常常是一票否决项</td></tr><tr><td>稳定性</td><td>限流额度、可用性、SLA 如何？</td><td>生产环境需要考虑多厂商容灾</td></tr></tbody></table><h2 id="模型的几种-档位" tabindex="-1">模型的几种&quot;档位&quot; <a class="header-anchor" href="#模型的几种-档位" aria-label="Permalink to &quot;模型的几种&quot;档位&quot;&quot;">​</a></h2><p>不同厂商的命名各不相同，但产品线大致可以分为几档：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>         能力</span></span>
<span class="line"><span>          ▲</span></span>
<span class="line"><span>          │   ● 旗舰 / 推理模型：最强，最慢，最贵</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          │        ● 主力模型：能力与成本的平衡点</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          │              ● 轻量模型：快、便宜，适合简单任务</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          └──────────────────────────────▶ 速度 / 成本优势</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>一个常见的误区是&quot;全部用最强的&quot;。实际上，Agent 中的大量调用（意图分类、简单抽取、格式转换、摘要）用轻量模型就足够了。合理的做法是<strong>分层使用</strong>：</p><ul><li><strong>路由层</strong>：用轻量模型判断请求类型和难度。</li><li><strong>主流程</strong>：用主力模型完成大部分对话和工具调用。</li><li><strong>难点环节</strong>：规划、复杂推理、代码修改交给旗舰或推理模型（见 <a href="/guide/02-llm-basics/reasoning-models">推理模型与扩展思考</a>）。</li></ul><h2 id="闭源-api、开源权重与本地部署" tabindex="-1">闭源 API、开源权重与本地部署 <a class="header-anchor" href="#闭源-api、开源权重与本地部署" aria-label="Permalink to &quot;闭源 API、开源权重与本地部署&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>优点</th><th>缺点</th><th>适合</th></tr></thead><tbody><tr><td>闭源 API</td><td>能力通常领先，开箱即用，无需运维</td><td>数据需发送给厂商，受限流和价格调整影响</td><td>绝大多数应用的起点</td></tr><tr><td>云上托管开源模型</td><td>模型可选择、可迁移，价格通常较低</td><td>能力与顶尖闭源模型可能有差距</td><td>成本敏感、希望避免锁定</td></tr><tr><td>私有化部署开源模型</td><td>数据完全可控，可微调</td><td>需要 GPU 和推理运维能力，前期投入大</td><td>强合规、内网环境、高调用量</td></tr></tbody></table><p>对大多数团队，建议的路径是：<strong>先用闭源 API 快速验证产品可行性，在有了评估集和真实流量数据之后，再考虑是否迁移到更便宜或可私有化的方案</strong>。过早投入私有化部署，往往会把精力消耗在运维上，而不是产品本身。</p><h2 id="选型流程-用数据说话" tabindex="-1">选型流程：用数据说话 <a class="header-anchor" href="#选型流程-用数据说话" aria-label="Permalink to &quot;选型流程：用数据说话&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 明确任务 ──▶ 2. 构建小评估集 ──▶ 3. 圈定 3~5 个候选 ──▶ 4. 实测打分</span></span>
<span class="line"><span>                    (30~100 条)                               │</span></span>
<span class="line"><span>                                                              ▼</span></span>
<span class="line"><span>6. 上线后持续监控 ◀── 5. 综合质量、延迟、成本做决定 ◀──────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>第 1 步：明确任务</strong>。写清楚输入是什么、期望输出是什么、什么叫&quot;做对&quot;。例如&quot;从用户邮件中抽取订单号和退款原因，输出 JSON&quot;。</p><p><strong>第 2 步：构建小评估集</strong>。从真实数据中挑选 30~100 条样本，覆盖常见情况和困难情况，标注期望结果。这一步最花时间，但也最有价值，后面的 <a href="/guide/14-evaluation/eval-design">评估集与指标设计</a> 会详细展开。</p><p><strong>第 3 步：圈定候选</strong>。根据合规要求、预算和语言先做一轮筛选。一般可以包括一个旗舰模型（作为能力上限的参照）、几个主力模型和一个轻量模型。</p><p><strong>第 4 步：实测打分</strong>。用同样的提示词跑完评估集，记录：</p><ul><li>正确率（或其他质量指标）</li><li>平均和 P95 延迟</li><li>平均每条的输入、输出 Token 和成本</li><li>格式错误率、工具调用错误率</li></ul><p><strong>第 5 步：综合决策</strong>。常见的结论形式是：&quot;轻量模型 A 正确率 91%，成本只有旗舰的十分之一，满足要求的 90% 阈值，选 A；把它答错的类型交给主力模型 B 兜底。&quot;</p><p><strong>第 6 步：持续监控</strong>。模型版本会更新，你的数据分布也会变化。评估集要变成回归测试的一部分，见 <a href="/guide/14-evaluation/regression">回归测试与持续评估</a>。</p><h2 id="为更换模型做好准备" tabindex="-1">为更换模型做好准备 <a class="header-anchor" href="#为更换模型做好准备" aria-label="Permalink to &quot;为更换模型做好准备&quot;">​</a></h2><p>模型选型不是一次性决策。为了让以后更换模型的成本最低，架构上可以：</p><ol><li><strong>统一接口</strong>：业务代码通过一层自己的封装调用模型，不直接散落着厂商 SDK 调用。使用 OpenAI 兼容接口能覆盖很多厂商，这也是本站示例统一使用它的原因（见 <a href="/guide/03-llm-api/providers">主流模型厂商 API 对比</a>）。</li><li><strong>配置化</strong>：模型名、Base URL、参数都放在配置里，不写死在代码中。本站示例使用的 <code>LLM_MODEL</code>、<code>OPENAI_BASE_URL</code> 就是这个思路。</li><li><strong>按任务配置模型</strong>：不同环节可以使用不同模型，例如 <code>ROUTER_MODEL</code>、<code>PLANNER_MODEL</code>。</li><li><strong>提示词与模型解耦但一起测试</strong>：同一提示词在不同模型上的效果可能差别很大，更换模型时要重新跑评估。</li></ol><p>一个按任务配置模型的 <code>.env</code> 示例（模型名仅为示例）：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OPENAI_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sk-...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OPENAI_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://api.deepseek.com</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LLM_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">deepseek-chat</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ROUTER_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">deepseek-chat</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PLANNER_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">deepseek-reasoner</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>只看排行榜</strong>：公开基准可能和你的任务差别很大，还存在数据污染的问题。排行榜用于圈定候选，不用于最终决策。</li><li><strong>只看单价</strong>：单价低但需要多次重试、输出冗长或要额外纠错的模型，单次任务的总成本可能更高。</li><li><strong>只试几个例子</strong>：凭几次对话的&quot;感觉&quot;选模型，结论很容易被随机性误导。</li><li><strong>忽略合规</strong>：开发完才发现客户不允许数据出境，只能推倒重来。合规要求应在选型的第一步确认。</li><li><strong>假设新版本一定更好</strong>：模型升级后，某些任务的表现可能变差，格式习惯也可能变化。升级前先跑回归评估。</li><li><strong>深度绑定单一厂商的专有特性</strong>：不是不能用，但要清楚迁移成本，并尽量把它们封装在适配层里。</li></ul><h2 id="小测" tabindex="-1">小测 <a class="header-anchor" href="#小测" aria-label="Permalink to &quot;小测&quot;">​</a></h2><p><strong>1. 模型 A 单价是模型 B 的一半，但在你的任务上 A 平均需要重试 1.5 次才能输出合法 JSON，B 一次成功。仅从 Token 成本看哪个更划算？</strong></p><details class="details custom-block"><summary>查看答案</summary><p>A 平均每个任务要调用约 2.5 次（1 次 + 1.5 次重试），按一半的单价算，成本约为 B 的 1.25 倍，而且延迟更高。所以 B 更划算。选型要按&quot;每完成一个任务的成本&quot;计算。</p></details><p><strong>2. 一个面向银行内部的知识助手项目，选型时第一件要确认的事是什么？</strong></p><details class="details custom-block"><summary>查看答案</summary><p>合规与数据要求：数据能否发送到外部 API、是否必须私有化部署、对模型来源有什么要求。这些约束会直接决定候选范围，应该在比较能力之前确认。</p></details><p><strong>3. 为什么建议在候选列表里放一个最强的旗舰模型，即使预算上并不打算用它？</strong></p><details class="details custom-block"><summary>查看答案</summary><p>它可以作为能力上限的参照。如果连旗舰模型在评估集上的表现都不理想，问题很可能出在任务定义、提示词或上下文上，而不是模型选择。如果旗舰模型表现很好，就能清楚看到便宜模型差距有多大，从而判断是否值得用更贵的模型。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="https://artificialanalysis.ai/" target="_blank" rel="noreferrer">Artificial Analysis</a>：模型质量、速度、价格的第三方对比</li><li><a href="https://lmarena.ai/" target="_blank" rel="noreferrer">LMArena</a>：基于人类投票的模型对比</li><li><a href="/guide/14-evaluation/why-evals">为什么评估是第一优先级</a></li><li>下一模块：<a href="/guide/03-llm-api/first-call">第一次调用大模型</a></li></ul>`,38)])])}const g=a(i,[["render",l]]);export{u as __pageData,g as default};
